static int font_find(lt_u32 cp)
{
    int lo = 0, hi = LT_FONT_COUNT - 1, mid;
    while (lo <= hi) {
        mid = (lo + hi) / 2;
        if (font_cp[mid] == cp) {
            return mid;
        }
        if (font_cp[mid] < cp) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

const lt_u8 *lt_font_glyph(lt_u32 cp)
{
    int i;
    if (cp < 0x7F && cp >= 0x20) {
        /* ASCII is dense and starts at index 0 */
        return font_bits[cp - 0x20];
    }
    i = font_find(cp);
    if (i < 0) {
        i = font_find((lt_u32)'?');
    }
    return font_bits[i];
}

lt_u32 lt_utf8_next(const char **s)
{
    const unsigned char *p = (const unsigned char *)*s;
    lt_u32 c = *p, cp;
    int n, i;
    if (c == 0) {
        return 0;
    }
    if (c < 0x80) {
        *s += 1;
        return c;
    }
    if (c >= 0xC2 && c <= 0xDF) {
        n = 1; cp = c & 0x1F;
    } else if (c >= 0xE0 && c <= 0xEF) {
        n = 2; cp = c & 0x0F;
    } else if (c >= 0xF0 && c <= 0xF4) {
        n = 3; cp = c & 0x07;
    } else {
        *s += 1;
        return 0xFFFD;
    }
    for (i = 1; i <= n; i++) {
        if ((p[i] & 0xC0) != 0x80) {
            *s += i;
            return 0xFFFD;
        }
        cp = (cp << 6) | (lt_u32)(p[i] & 0x3F);
    }
    *s += n + 1;
    if ((n == 2 && cp < 0x800) || (n == 3 && cp < 0x10000) ||
        cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) {
        return 0xFFFD;
    }
    return cp;
}
